    if(preg_match('~^/(?:data|php|lib|scripts|node_modules|public)(?:/|$)~',$path)) az_text(404,'Not found');
    az_open(); $origin=az_origin(); $products=az_catalog(); $store=az_store();
    if($path==='/sitemap.xml') {
        $pages=['/','/shop','/shop?gender=women','/shop?gender=men','/shop?category=accessory','/shop?collection=originals','/western','/about','/faq','/size-guide','/shipping','/contact','/privacy','/terms','/returns-policy','/stitching','/gift-cards','/rewards'];
        foreach($products as $p) if(empty($p['unlisted'])) $pages[]='/product/'.$p['slug']; $xml='<?xml version="1.0" encoding="UTF-8"?>' . "\n".'<urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">' . "\n";
        foreach($pages as $page) $xml.='<url><loc>'.az_h($origin.$page)."</loc></url>\n"; az_text(200,$xml.'</urlset>','application/xml; charset=utf-8');
    }
    $title='Aarzu · Shalwar Kameez with the Soul of Pakistan'; $desc='Designer favourites for less and our own Aarzu Originals. Cash on delivery all over Pakistan.'; $image=$origin.'/brand/aarzu-logo-stacked.png'; $type='website'; $graph=[]; $product=null;
    if(preg_match('~^/product/([\w-]+)~',$path,$m)) $product=az_find(array_values($products),fn($p)=>$p['slug']===$m[1]);
    if($product) { $title=$product['title'].' · '.az_rs($product['price']).' | Aarzu'; $desc=az_unbranded($product['description']??'',($product['collection']??'')==='originals'?null:($product['source']['brand']??null)); $desc=function_exists('mb_substr')?mb_substr($desc,0,200):substr($desc,0,200); $im=$product['images'][0]??''; $image=preg_match('~^https?://~',$im)?$origin.'/img?u='.rawurlencode($im):$origin.$im; $type='product'; }
    elseif(str_starts_with($path,'/shop')) $title='Shop shalwar kameez | Aarzu'; elseif(str_starts_with($path,'/western')) $title='Aarzu West · Coming soon';
    $tags='<meta property="og:site_name" content="Aarzu"><meta property="og:type" content="'.$type.'"><meta property="og:title" content="'.az_h($title).'"><meta property="og:description" content="'.az_h($desc).'"><meta property="og:image" content="'.az_h($image).'"><meta property="og:url" content="'.az_h($origin.$path).'"><meta name="twitter:card" content="summary_large_image"><link rel="canonical" href="'.az_h($origin.$path).'">';
    if(preg_match('~^/(admin|checkout|order|account)~',$path)) $tags.='<meta name="robots" content="noindex">';
    if($path==='/'||$path==='/index.html') { $graph=[['@type'=>'Organization','@id'=>$origin.'/#organization','name'=>$store['name']??'Aarzu','alternateName'=>$store['urdu']??'آرزو','url'=>$origin.'/','logo'=>$origin.'/brand/aarzu-logo.png'],['@type'=>'WebSite','@id'=>$origin.'/#website','name'=>$store['name']??'Aarzu','url'=>$origin.'/','publisher'=>['@id'=>$origin.'/#organization'],'potentialAction'=>['@type'=>'SearchAction','target'=>['@type'=>'EntryPoint','urlTemplate'=>$origin.'/shop?q={search_term_string}'],'query-input'=>'required name=search_term_string']]]; }
    if($product) { $p=$product; $url=$origin.'/product/'.$p['slug']; $reviews=array_filter(az_db('reviews'),fn($r)=>$r['productId']===$p['id']&&$r['rating']>=1); $data=['@type'=>'Product','@id'=>$url.'#product','name'=>$p['title'],'description'=>$desc,'sku'=>$p['id'],'url'=>$url,'image'=>array_map(fn($u)=>preg_match('~^https?://~',$u)?$origin.'/img?u='.rawurlencode($u):$origin.$u,$p['images']),'offers'=>['@type'=>'Offer','url'=>$url,'priceCurrency'=>'PKR','price'=>$p['price'],'availability'=>'https://schema.org/'.(array_sum($p['stock'])>0?'InStock':'OutOfStock'),'itemCondition'=>'https://schema.org/NewCondition','seller'=>['@type'=>'Organization','name'=>'Aarzu']]]; if(($p['collection']??'')==='originals') $data['brand']=['@type'=>'Brand','name'=>'Aarzu']; if($reviews) $data['aggregateRating']=['@type'=>'AggregateRating','ratingValue'=>round(array_sum(array_column($reviews,'rating'))/count($reviews),1),'reviewCount'=>count($reviews),'bestRating'=>5,'worstRating'=>1]; $graph[]=$data; $tags.='<meta property="product:price:amount" content="'.$p['price'].'"><meta property="product:price:currency" content="PKR">'; }
    if($graph) $tags.='<script type="application/ld+json">'.str_replace('<','\u003c',json_encode(['@context'=>'https://schema.org','@graph'=>$graph],AZ_JSON)).'</script>';
